(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(y * 0.012 + t * 0.15) * 20 + Math.cos(x * 0.008 - t * 0.1) * 15;
  const w1y = Math.cos(x * 0.013 - t * 0.12) * 18 + Math.sin(y * 0.009 + t * 0.18) * 12;
  const wx2 = Math.sin((y + w1y) * 0.015 + t * 0.2) * 12 + Math.cos((x + w1x) * 0.01 - t * 0.15) * 8;
  const wy2 = Math.cos((x + w1x) * 0.014 - t * 0.18) * 10 + Math.sin((y + w1y) * 0.011 + t * 0.22) * 7;
  const sx = x + w1x + wx2, sy = y + w1y + wy2;
  const src = [
    [160+Math.sin(t*0.5)*100, 80+Math.cos(t*0.35)*50, 0.07, 2.2],
    [320+Math.cos(t*0.4)*100, 160+Math.sin(t*0.6)*50, 0.09, 1.8],
    [240+Math.sin(t*0.25+2)*140, 120+Math.cos(t*0.4+1)*90, 0.055, 2.5],
    [120+Math.cos(t*0.7+1)*80, 180+Math.sin(t*0.5+3)*60, 0.11, 1.6],
    [360+Math.sin(t*0.35+4)*90, 60+Math.cos(t*0.8+2)*70, 0.065, 2.8],
    [240+Math.cos(t*0.3+5)*120, 200+Math.sin(t*0.45)*80, 0.08, 2.1],
    [80+Math.sin(t*0.55+3)*70, 100+Math.cos(t*0.65+1)*60, 0.075, 1.9],
    [400+Math.cos(t*0.45+2)*60, 200+Math.sin(t*0.5+4)*50, 0.1, 2.4]
  ];
  let aS = 0, iS = 0, iS2 = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    iS2 += Math.sin(d*f*0.5 - t*sp*0.4 + 3.0);
  }
  const act = aS/8, inh = iS/8, inh2 = iS2/8;
  const bg1 = (Math.sin(sx*0.035+sy*0.02+t*0.7) + Math.sin(sx*0.025-sy*0.035+t*0.9))/2;
  const bg2 = (Math.sin((sx+sy)*0.1+t*2.2) + Math.sin((sx-sy)*0.08-t*1.8))/2;
  const bg3 = Math.sin(sx*0.06+sy*0.04-t*1.3) * Math.cos(sx*0.04-sy*0.06+t*0.8);
  const bg = bg1*0.5 + bg2*0.3 + bg3*0.2;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.045-ang*3.5-t*1.3) + Math.sin(dist*0.035+ang*5-t*1.0))*0.35;
  const spiral2 = Math.sin(dist*0.06+ang*2-t*2.0)*0.2;
  const cellX = sx*0.12, cellY = sy*0.12;
  const cellNoise = Math.sin(Math.sin(cellX+t*0.3)*2.5 + Math.cos(cellY-t*0.2)*2.5 + t*0.5) * 0.2;
  const rd1 = Math.tanh((act - inh*0.65 + bg*0.35 + spiral + spiral2)*2.0);
  const rd2 = Math.tanh((act*0.8 - inh2*0.5 + bg*0.2 - spiral*0.3)*1.8);
  const reaction = rd1*0.7 + rd2*0.3;
  const edgeFactor = Math.abs(reaction) > 0.6 ? 1.0 + (Math.abs(reaction)-0.6)*0.5 : 1.0;
  const fine = Math.sin(sx*0.3+sy*0.25+t*3)*Math.sin(sx*0.25-sy*0.3-t*2.5)*0.1;
  const blend = reaction*0.8 + cellNoise*0.1 + fine*0.1;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[10,40,82],[12,82,102],[16,135,132],[50,185,168],
    [140,205,145],[210,205,90],[225,165,65],[210,105,70],[175,65,85],
    [115,38,82],[55,20,68],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sf = f*f*(3-2*f);
  const lum = 0.85 + Math.sin(reaction*Math.PI)*0.15;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edgeFactor)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edgeFactor)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edgeFactor)|0
  ];
}
